class Solution:
    def largestMultipleOfThree(self, digits):
        n = len(digits)
        best = []
        for mask in range(1 << n):
            cur = [digits[i] for i in range(n) if mask >> i & 1]
            if cur and sum(cur) % 3 == 0:
                if len(cur) > len(best) or (len(cur) == len(best) and sorted(cur, reverse=True) > best):
                    best = sorted(cur, reverse=True)
        return ''.join(map(str, best)).lstrip('0') if best else ''

