class Solution {
public:
    string largestMultipleOfThree(vector<int>& digits) {
        int n = digits.size();
        vector<int> best;
        for (int mask = 0; mask < (1 << n); ++mask) {
            vector<int> cur;
            long long s = 0;
            for (int i = 0; i < n; ++i)
                if (mask >> i & 1) { cur.push_back(digits[i]); s += digits[i]; }
            if (!cur.empty() && s % 3 == 0) {
                sort(cur.rbegin(), cur.rend());
                if (cur.size() > best.size() ||
                   (cur.size() == best.size() && cur > best)) best = cur;
            }
        }
        string res;
        for (int d : best) res += '0' + d;
        int z = res.find_first_not_of('0');
        return z == string::npos ? "" : res.substr(z);
    }
};

