class Solution {
    public String largestMultipleOfThree(int[] digits) {
        int n = digits.length;
        List<Integer> best = new ArrayList<>();
        for (int mask = 0; mask < (1 << n); mask++) {
            List<Integer> cur = new ArrayList<>();
            long s = 0;
            for (int i = 0; i < n; i++)
                if ((mask >> i & 1) != 0) { cur.add(digits[i]); s += digits[i]; }
            if (!cur.isEmpty() && s % 3 == 0) {
                cur.sort(Collections.reverseOrder());
                if (cur.size() > best.size() ||
                   (cur.size() == best.size() && greater(cur, best))) best = new ArrayList<>(cur);
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int d : best) sb.append(d);
        String r = sb.toString().replaceFirst("^0+", "");
        return r.isEmpty() ? "" : r;
    }
    private boolean greater(List<Integer> a, List<Integer> b) {
        for (int i = 0; i < a.size(); i++) {
            int c = a.get(i).compareTo(b.get(i));
            if (c != 0) return c > 0;
        }
        return false;
    }
}

