class Solution {
    public String largestMultipleOfThree(int[] digits) {
        List<List<Integer>> dp = new ArrayList<>();
        for (int i = 0; i < 3; i++) dp.add(new ArrayList<>());
        for (int d : digits) {
            List<List<Integer>> old = new ArrayList<>();
            for (List<Integer> l : dp) old.add(new ArrayList<>(l));
            for (int r = 0; r < 3; r++) {
                List<Integer> cand = new ArrayList<>(old.get((r - d % 3 + 3) % 3));
                cand.add(d);
                cand.sort(Collections.reverseOrder());
                List<Integer> cur = new ArrayList<>(dp.get(r));
                cur.sort(Collections.reverseOrder());
                if (cand.size() > cur.size() || (cand.size() == cur.size() && cmp(cand, cur) > 0))
                    dp.set(r, cand);
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int x : dp.get(0)) sb.append(x);
        String r = sb.toString().replaceFirst("^0+", "");
        return r.isEmpty() ? "" : r;
    }
    private int cmp(List<Integer> a, List<Integer> b) {
        for (int i = 0; i < a.size(); i++) {
            int c = a.get(i).compareTo(b.get(i));
            if (c != 0) return c;
        }
        return 0;
    }
}

