class Solution:
    def largestMultipleOfThree(self, digits):
        cnt = [0] * 10
        s = 0
        for d in digits:
            cnt[d] += 1
            s += d
        def remove(k, residues):
            nonlocal cnt
            while k and residues:
                for d in range(10):
                    if d % 3 == residues[0] and cnt[d]:
                        cnt[d] -= 1
                        k -= 1
                        break
                else:
                    residues.pop(0)
                    continue
                if k == 0:
                    break
            return k == 0
        r = s % 3
        if r == 1:
            if not remove(1, [1]) and not remove(2, [2]):
                return ""
        elif r == 2:
            if not remove(1, [2]) and not remove(2, [1]):
                return ""
        res = []
        for d in range(9, -1, -1):
            res.append(str(d) * cnt[d])
        ans = ''.join(res).lstrip('0')
        return ans

