class Solution {
public:
    string largestMultipleOfThree(vector<int>& digits) {
        array<int, 10> cnt{};
        cnt.fill(0);
        long long s = 0;
        for (int d : digits) { cnt[d]++; s += d; }
        auto tryRemove = [&](int k, int res) {
            for (int d = 0; d < 10 && k > 0; ++d)
                while (k > 0 && d % 3 == res && cnt[d]) { cnt[d]--; k--; }
            return k == 0;
        };
        int r = s % 3;
        if (r == 1) {
            if (!tryRemove(1, 1) && !tryRemove(2, 2)) return "";
        } else if (r == 2) {
            if (!tryRemove(1, 2) && !tryRemove(2, 1)) return "";
        }
        string out;
        for (int d = 9; d >= 0; --d) out.append(cnt[d], '0' + d);
        size_t z = out.find_first_not_of('0');
        return z == string::npos ? "" : out.substr(z);
    }
};

