class Solution {
    public String largestMultipleOfThree(int[] digits) {
        int[] cnt = new int[10];
        long s = 0;
        for (int d : digits) { cnt[d]++; s += d; }
        int r = (int)(s % 3);
        if (r == 1) {
            if (!remove(cnt, 1, 1) && !remove(cnt, 2, 2)) return "";
        } else if (r == 2) {
            if (!remove(cnt, 1, 2) && !remove(cnt, 2, 1)) return "";
        }
        StringBuilder sb = new StringBuilder();
        for (int d = 9; d >= 0; d--)
            for (int i = 0; i < cnt[d]; i++) sb.append(d);
        String res = sb.toString().replaceFirst("^0+", "");
        return res.isEmpty() ? "" : res;
    }
    private boolean remove(int[] cnt, int k, int res) {
        for (int d = 0; d < 10 && k > 0; d++)
            while (k > 0 && d % 3 == res && cnt[d] > 0) { cnt[d]--; k--; }
        return k == 0;
    }
}

