    const cnt = new Array(10).fill(0);
    let s = 0;
    for (const d of digits) { cnt[d]++; s += d; }
    const remove = (k, res) => {
        for (let d = 0; d < 10 && k > 0; d++)
            while (k > 0 && d % 3 === res && cnt[d] > 0) { cnt[d]--; k--; }
        return k === 0;
    };
